#!/usr/bin/env node
// Copies the authoritative public/academy/data/pricing.json into the Edge
// Functions bundle (supabase/functions/_shared/pricing-rules.ts).
//
//   node tools/payments-v12/sync-pricing.mjs          write the generated file
//   node tools/payments-v12/sync-pricing.mjs --check  exit 1 when it is stale
//   node tools/payments-v12/sync-pricing.mjs --sql    print the public.plans upsert
//
// After changing prices: run it, redeploy the functions and run the --sql output
// in the Supabase SQL editor, so the site, functions and database agree.
import { readFileSync, writeFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const root = join(dirname(fileURLToPath(import.meta.url)), '..', '..');
export const SOURCE = join(root, 'public/academy/data/pricing.json');
export const TARGET = join(root, 'supabase/functions/_shared/pricing-rules.ts');
const ISO = /^[A-Z]{3}$/;

function fail(message) { throw new Error('pricing.json: ' + message); }

export function validatePricing(p) {
  if (!p || typeof p !== 'object' || Array.isArray(p)) fail('not an object');
  if (p.baseCurrency !== 'TWD') fail('baseCurrency must be TWD');
  if (!Array.isArray(p.plans) || !p.plans.length) fail('plans missing');
  const ids = new Set();
  for (const plan of p.plans) {
    if (!/^[a-z0-9-]{1,40}$/.test(plan?.id ?? '') || ids.has(plan.id)) fail('invalid or duplicate plan id');
    ids.add(plan.id);
    if (!Number.isSafeInteger(plan.amountTwd) || plan.amountTwd < 1) fail(`plan ${plan.id} amountTwd`);
    if (!Number.isSafeInteger(plan.durationDays) || plan.durationDays < 1 || plan.durationDays > 3660) fail(`plan ${plan.id} durationDays`);
    if (typeof plan.title !== 'string' || typeof plan.titleEn !== 'string') fail(`plan ${plan.id} titles`);
    if (/[#'\\]/.test(plan.title + plan.titleEn)) fail(`plan ${plan.id} titles must not contain # ' or \\`);
  }
  const cc = p.chargeCurrencies;
  if (!cc || typeof cc !== 'object') fail('chargeCurrencies missing');
  for (const provider of ['paypal', 'ecpay']) {
    if (!Array.isArray(cc[provider]) || !cc[provider].length || cc[provider].some(c => !ISO.test(c))) fail(`chargeCurrencies.${provider}`);
  }
  if (cc.ecpay.length !== 1 || cc.ecpay[0] !== 'TWD') fail('ECPay charges TWD only');
  if (!cc.paypal.includes(p.fallbackChargeCurrency)) fail('fallbackChargeCurrency must be a PayPal charge currency');
  if (!Array.isArray(p.zeroDecimal) || p.zeroDecimal.some(c => !ISO.test(c)) || !p.zeroDecimal.includes('TWD')) fail('zeroDecimal');
  if (!Number.isSafeInteger(p.fxMaxAgeDays) || p.fxMaxAgeDays < 1) fail('fxMaxAgeDays');
  if (!p.freePolicy || p.freePolicy.freeStagesPerCourse !== 1) fail('freePolicy.freeStagesPerCourse must be 1 (stage_index 0 is free)');
  return p;
}

export function pickRules(p) {
  validatePricing(p);
  return {
    version: p.version,
    baseCurrency: p.baseCurrency,
    plans: p.plans.map(({ id, title, titleEn, amountTwd, durationDays }) => ({ id, title, titleEn, amountTwd, durationDays })),
    freeStagesPerCourse: p.freePolicy.freeStagesPerCourse,
    chargeCurrencies: { paypal: [...p.chargeCurrencies.paypal], ecpay: [...p.chargeCurrencies.ecpay] },
    fallbackChargeCurrency: p.fallbackChargeCurrency,
    zeroDecimal: [...p.zeroDecimal],
    rounding: p.rounding,
    fxMaxAgeDays: p.fxMaxAgeDays,
  };
}

export function render(rules) {
  return `// GENERATED by tools/payments-v12/sync-pricing.mjs from public/academy/data/pricing.json.
// Do not edit by hand: change pricing.json, then run the script again.
import type { PricingRules } from './pricing.ts';

export const PRICING_RULES: PricingRules = ${JSON.stringify(rules, null, 2)};
`;
}

export function plansSql(rules) {
  const q = s => `'${String(s).replace(/'/g, "''")}'`;
  const rows = rules.plans.map((p, i) => `  (${q(p.id)}, ${q(p.title)}, ${q(p.titleEn)}, ${p.amountTwd}, ${p.durationDays}, ${i + 1})`).join(',\n');
  return `insert into public.plans (id, title, title_en, amount_twd, duration_days, sort_order) values\n${rows}\non conflict (id) do update set title = excluded.title, title_en = excluded.title_en, amount_twd = excluded.amount_twd,\n  duration_days = excluded.duration_days, sort_order = excluded.sort_order, active = true, updated_at = now();\n`;
}

const isMain = process.argv[1] && fileURLToPath(import.meta.url) === process.argv[1];
if (isMain) {
  const rules = pickRules(JSON.parse(readFileSync(SOURCE, 'utf8')));
  const output = render(rules);
  if (process.argv.includes('--sql')) {
    process.stdout.write(plansSql(rules));
  } else if (process.argv.includes('--check')) {
    let current = '';
    try { current = readFileSync(TARGET, 'utf8'); } catch { /* missing counts as stale */ }
    if (current !== output) { console.error('pricing-rules.ts is stale: run node tools/payments-v12/sync-pricing.mjs'); process.exit(1); }
    console.log('pricing rules in sync');
  } else {
    writeFileSync(TARGET, output);
    console.log('wrote ' + TARGET);
  }
}
